(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['area','compliance','strain','method'],el=Object.fromEntries(keys.map(k=>[k,document.getElementById('M01-'+k)]));let cur={};function draw(){let area=+el.area.value,C=+el.compliance.value,e=+el.strain.value,method=el.method.value,factor=method==='crosshead'?1+400*C:1,modulus=2000*10/area/factor,F=20000*e,local=50*e,cross=local+C*F;cur={area,compliance:C,strain:e,method,modulus,force:F,localExtension:local,crossheadExtension:cross,displayStrain:e*factor,stress:F/area};['area','compliance','strain'].forEach(k=>document.getElementById('M01-'+k+'-value').textContent=cur[k].toFixed(k==='area'?1:4));let X=x=>85+x/.045*600,Y=y=>300-y/85*240,s='<rect width="800" height="360" fill="#f5f8f8"/>';for(let i=0;i<=4;i++)s+=`<line x1="${X(i*.01)}" x2="${X(i*.01)}" y1="40" y2="300" stroke="#dde5e6"/><text x="${X(i*.01)}" y="320" text-anchor="middle">${i}</text>`;for(let y=0;y<=80;y+=20)s+=`<text x="70" y="${Y(y)+5}" text-anchor="end">${y}</text>`;s+=`<path d="M${X(0)},${Y(0)} L${X(.02*factor)},${Y(400/area)}" stroke="#186c94" stroke-width="4"/><path d="M${X(0)},${Y(0)} L${X(.02)},${Y(40)}" stroke="#188777" stroke-width="2" stroke-dasharray="5 4"/><circle cx="${X(e*factor)}" cy="${Y(F/area)}" r="7" fill="#d27839"/><text x="90" y="25">${zh?'蓝：所选分析；绿虚线：材料真实响应':'Blue: selected analysis; green dashed: actual material'}</text><text x="390" y="350" text-anchor="middle">${zh?'计算应变 / %':'Calculated strain / %'}</text><text transform="translate(20 180) rotate(-90)" text-anchor="middle">${zh?'工程应力 / MPa':'Engineering stress / MPa'}</text>`;document.getElementById('M01-plot').innerHTML=s;document.getElementById('M01-values').textContent=(zh?'表观模量 ':'Apparent modulus ')+modulus.toFixed(2)+' MPa · F='+F.toFixed(2)+' N · '+(zh?'局部伸长 ':'Local extension ')+local.toFixed(4)+' mm · '+(zh?'横梁位移 ':'Crosshead travel ')+cross.toFixed(4)+' mm';return {...cur}}function set(p){keys.forEach(k=>{if(k in p)el[k].value=p[k]});return draw()}function reset(){return set({area:10,compliance:.001,strain:.005,method:'crosshead'})}keys.forEach(k=>el[k].addEventListener(k==='method'?'change':'input',draw));document.getElementById('M01-reset').addEventListener('click',reset);window.CourseLab={set,state:()=>({...cur}),reset,destroy(){}};reset()})();